import { type Channel, type NotificationKey, isChannel, isNotificationKey } from '../notifications/keys';

/** Container of the notification mapping Custom Objects. */
export const MAPPINGS_CONTAINER = 'notification-mappings';

/** SendGrid dynamic template IDs, for email and SMS templates alike. */
export const TEMPLATE_ID_PATTERN = /^d-[0-9a-f]{32}$/;

/**
 * Maps one notification and channel to the SendGrid dynamic template that is sent. SMS templates are
 * SendGrid templates too (named with an "[SMS] " prefix); the connector reads their text at send time.
 */
export type NotificationMapping = {
  schemaVersion: 2;
  notification: NotificationKey;
  channel: Channel;
  enabled: boolean;
  templateId: string;
};

export const mappingKey = (notification: NotificationKey, channel: Channel): string =>
  `${notification}-${channel}`;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/**
 * Validates a Custom Object value. Returns undefined for anything that is not a usable mapping, so the
 * connector ignores it and the Merchant Center shows it as "Invalid".
 *
 * Schema 1 email mappings (`email.sendGridTemplateId`) are read as they are. Schema 1 SMS mappings held the
 * text itself and have no template to point to, so they are invalid until they are edited.
 */
export const parseNotificationMapping = (value: unknown): NotificationMapping | undefined => {
  if (!isRecord(value)) return undefined;
  const { notification, channel, enabled } = value;
  if (!isNotificationKey(notification) || !isChannel(channel) || typeof enabled !== 'boolean') {
    return undefined;
  }

  let templateId: unknown;
  if (value.schemaVersion === 2) {
    templateId = value.templateId;
  } else if (value.schemaVersion === 1 && channel === 'email' && isRecord(value.email)) {
    templateId = value.email.sendGridTemplateId;
  } else {
    return undefined;
  }
  if (typeof templateId !== 'string' || !TEMPLATE_ID_PATTERN.test(templateId.trim())) return undefined;
  return { schemaVersion: 2, notification, channel, enabled, templateId: templateId.trim() };
};
